using System;using System.IO;using UnityEngine;using UnityEditor;
namespace LWS.TruckSumo.Editor {
public static class SumoPreviewAuthoring {
 public static void Create(SumoMatch match){Directory.CreateDirectory("Assets/TruckSumo/Art");for(int i=0;i<4;i++){float a=i*Mathf.PI*.5f;var t=match.fighters[i].truck;var position=new Vector3(Mathf.Sin(a)*8,.7f,Mathf.Cos(a)*8);t.transform.SetPositionAndRotation(position,Quaternion.LookRotation(new Vector3(-position.x,0,-position.z)));t.body.position=position;t.body.rotation=t.transform.rotation;t.ApplyColor(match.setup.players[i].color);var block=new MaterialPropertyBlock();block.SetColor("_BaseColor",match.setup.players[i].color);foreach(var r in match.fighters[i].trim)r.SetPropertyBlock(block);}var c=match.broadcast.view;var positionBefore=c.transform.position;var rotationBefore=c.transform.rotation;foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(512,288),new Vector2Int(1200,900)}){bool close=size.x==1200;var rt=new RenderTexture(size.x,size.y,24);rt.Create();var target=c.targetTexture;var old=RenderTexture.active;c.targetTexture=rt;c.orthographic=!close;if(close){var truck=match.fighters[0].truck;match.broadcast.Pose(truck.transform.position+Vector3.up*.7f,new Vector3(3.5f,1.4f,-4),46,true);}else{c.transform.SetPositionAndRotation(positionBefore,rotationBefore);match.fit.Apply();}c.Render();RenderTexture.active=rt;var image=new Texture2D(size.x,size.y,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,size.x,size.y),0,0);image.Apply();string path=size.x==512?"Assets/TruckSumo/Art/Menu Preview.png":"Logs/TruckSports/SevenSports/sumo-"+(close?"outfit-close":size.x.ToString())+".png";File.WriteAllBytes(path,image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);c.targetTexture=target;RenderTexture.active=old;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}c.orthographic=true;c.transform.SetPositionAndRotation(positionBefore,rotationBefore);match.broadcast.Pose(Vector3.zero,new Vector3(0,15,-26),58,true);match.fit.Apply();string preview="Assets/TruckSumo/Art/Menu Preview.png";AssetDatabase.ImportAsset(preview);var importer=(TextureImporter)AssetImporter.GetAtPath(preview);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.mipmapEnabled=false;importer.SaveAndReimport();}
}
}
